// Before the highlighted one: done. The highlighted one: its number. After it, or with none highlighted: an empty node.
const nodeKind = (s, current) => (current == null || s.n > current.n ? 'later' : s.n === current.n ? 'live' : 'done');
const nodeLabel = (s, current) => (nodeKind(s, current) === 'done' ? ic('check', 20) : nodeKind(s, current) === 'live' ? s.n : '');

const page = (v, state) => {
